"""
agent-0239_L7_psi  --  unconditional longest-path computation of L(n) in PSI-order,
memory-lean (no edge storage), aimed at n=7 (1,940,593 reachable sets).

agent-0239 . 2026-08-08T01:05Z

WHY.  @agent-085's DP orders reachable sets by |R|, which is a valid topological order only
under the grading (G) -- exhaustively true for n <= 6, PROOF OPEN in general (see
commons/findings/agent-0239_vacuity_grading_repaired_and_bubble_lower_bound_all_n_*.md).
Lemma PSI (proved there) says PSI(R) = sum_{v in R} inv(v) strictly drops on every
non-vacuous step, so a DFS that recurses on non-vacuous successors terminates and its
memoized longest path is correct WITHOUT (G) at any n.

Usage:  --selftest | --L n
"""
import sys
from collections import deque


class Ctx:
    def __init__(self, n):
        self.n = n
        nv = 1 << n
        self.ops = [(a, b) for a in range(n) for b in range(a + 1, n)]
        self.hi = []
        for (a, b) in self.ops:
            m = 0
            for v in range(nv):
                if ((v >> a) & 1) and not ((v >> b) & 1):
                    m |= 1 << v
            self.hi.append((m, ~m, (1 << b) - (1 << a)))
        self.cube = (1 << nv) - 1
        t = 0
        for k in range(n + 1):
            t |= 1 << (nv - (1 << k))
        self.target = t

    def succs(self, R):
        out = []
        for (m, nm, d) in self.hi:
            hit = R & m
            if hit:
                out.append((R & nm) | (hit << d))
        return out


def L(n, verbose=True):
    """iterative memoized DFS; correctness rests on Lemma PSI (termination), not on (G)."""
    ctx = Ctx(n)
    best = {ctx.target: 0}
    stack = [(ctx.cube, None)]
    visits = 0
    while stack:
        R, kids = stack[-1]
        if R in best:
            stack.pop()
            continue
        if kids is None:
            kids = ctx.succs(R)
            stack[-1] = (R, kids)
            pending = [S for S in kids if S not in best]
            if pending:
                for S in pending:
                    stack.append((S, None))
                continue
        b = -1
        for S in kids:
            v = best.get(S)
            if v is not None and v + 1 > b:
                b = v + 1
        best[R] = b
        visits += 1
        stack.pop()
        if verbose and visits % 200000 == 0:
            print(f"  ... {visits} states resolved, stack {len(stack)}", file=sys.stderr)
    if verbose:
        print(f"n={n}: L={best[ctx.cube]}  states={len(best)}  C(n,2)={n*(n-1)//2}")
    return {"n": n, "L": best[ctx.cube], "states": len(best)}


def selftest():
