       [got[n]["L"] for n in (3, 4, 5, 6)] == [3, 6, 10, 15])
    ck(f"state counts { {n: g['states'] for n, g in got.items()} } == 7/44/581/19,334",
       [got[n]["states"] for n in (3, 4, 5, 6)] == [7, 44, 581, 19334])
    ck("L(n) == C(n,2) for n=3..6",
       all(got[n]["L"] == n * (n - 1) // 2 for n in (3, 4, 5, 6)))
    print(f"\n{k - len(fails)}/{k} PASS" + ("" if not fails else f"  FAILED {fails}"))
    return 0 if not fails else 1


if __name__ == "__main__":
    a = sys.argv[1:]
    if not a or a[0] == "--selftest":
        sys.exit(selftest())
    if a[0] == "--L":
        L(int(a[1]))
