import sys


class Ctx:
    def __init__(self, n):
        self.n = n
        nv = 1 << n
        self.ops = [(a, b) for a in range(n) for b in range(a + 1, n)]
        self.hi = []
        for (a, b) in self.ops:
            m = 0
            for v in range(nv):
                if ((v >> a) & 1) and not ((v >> b) & 1):
                    m |= 1 << v
            self.hi.append((m, ~m, (1 << b) - (1 << a)))
        self.cube = (1 << nv) - 1

    def succs(self, R):
        out = []
        for (m, nm, d) in self.hi:
            hit = R & m
            if hit:
                out.append((R & nm) | (hit << d))
        return out


def cell(n, k, B=None, verbose=True):
    """decide M_k(n) <= B by exploring only the |R| > B corridor."""
    ctx = Ctx(n)
    if B is None:
        B = (1 << (n - 1)) + (1 << (n - 1 - k))
    cur = {ctx.cube}
    widths = []
    for j in range(1, k + 1):
        nxt = set()
        for R in cur:
            for R2 in ctx.succs(R):
                if bin(R2).count("1") > B:
                    nxt.add(R2)
        cur = nxt
        widths.append(len(cur))
        if not cur:
            break
    over = max((bin(R).count("1") for R in cur), default=None)
    res = {"n": n, "k": k, "B": B, "corridor_widths": widths,
           "states_at_depth_k_above_B": len(cur), "max_above_B": over,
           "M_k_le_B": len(cur) == 0}
    if verbose:
        print(f"n={n} k={k}: testing M_k <= B = {B} = 2^{n-1}+2^{n-1-k}")
        print(f"  corridor widths by depth (states with |R| > B): {widths}")
        if res["M_k_le_B"]:
            print(f"  NO word of {k} non-vacuous comparators keeps |R| > {B}  ->  M_{k}({n}) <= {B}")
            print(f"  and the bubble chain C_{k} attains {B} (Proposition C)  ->  M_{k}({n}) = {B}")
        else:
            print(f"  *** CONJECTURE M REFUTED at this cell: {len(cur)} states at depth {k} "
                  f"with |R| up to {over} > {B}")
    return res


def selftest():
    fails, k_ = [], 0

    def ck(name, cond):
        nonlocal k_
        k_ += 1
        print(("PASS " if cond else "FAIL ") + name)
        if not cond:
            fails.append(name)

    # agreement with the exhaustive level-BFS values I already published (n<=8)
    for (n, k, B) in [(5, 4, 17), (6, 5, 33), (7, 6, 65), (8, 7, 129)]:
        r = cell(n, k, B, verbose=False)
        ck(f"M_{k}({n}) <= {B} confirmed by corridor search (matches exhaustive level-BFS)",
           r["M_k_le_B"])
    # negative control: B one BELOW the true maximum must be violated
    for (n, k, B) in [(5, 4, 16), (6, 5, 32), (7, 6, 64)]:
        r = cell(n, k, B, verbose=False)
        ck(f"negative control: M_{k}({n}) <= {B} is correctly REFUTED (true max is {B+1})",
           not r["M_k_le_B"] and r["max_above_B"] == B + 1)
    print(f"\n{k_ - len(fails)}/{k_} PASS" + ("" if not fails else f"  FAILED {fails}"))
    return 0 if not fails else 1


if __name__ == "__main__":
    a = sys.argv[1:]
    if not a or a[0] == "--selftest":
        sys.exit(selftest())
    if a[0] == "--cell":
        cell(int(a[1]), int(a[2]), int(a[3]) if len(a) > 3 else None)
    else:
        print(__doc__)

